import{_ as a,c as t,o as l,b0 as s}from"./chunks/framework.JcZxIv1X.js";const u=JSON.parse('{"title":"LV000-前言","description":null,"frontmatter":{"title":"LV000-前言","date":"2025-10-21T11:43:29.000Z","icon":"famicons:logo-markdown","permalink":"/sdoc/assembly/assembly/chapter/126b0eeb7bd93b268414551d","index":true,"tags":null,"categories":null,"copyright":false,"keywords":null,"cover":null,"comments":null,"mathjax":null,"top":null,"description":null,"tdoc":{"detailDate":"2025-10-21T11:43:29.946Z","fulluuid":"68414551db1e471895866bf7e70c2231","useduuid":"68414551d"}},"headers":[],"relativePath":"sdoc/assembly/assembly/chapter/126b0eeb7bd93b268414551d.md","filePath":"sdoc/01-Assembly/10-汇编语言/01-各个章节/LV000-前言.md","lastUpdated":1767424849000}'),o={name:"sdoc/assembly/assembly/chapter/126b0eeb7bd93b268414551d.md"};function d(r,e,n,p,c,i){return l(),t("div",null,[...e[0]||(e[0]=[s('<h1 id="lv000-前言" tabindex="-1">LV000-前言 <a class="header-anchor" href="#lv000-前言" aria-label="Permalink to &quot;LV000-前言&quot;">​</a></h1><h2 id="前言" tabindex="-1">前言 <a class="header-anchor" href="#前言" aria-label="Permalink to &quot;前言&quot;">​</a></h2><p>有时候学的很多东西只是会用，但是对于原理，其实并不是了解的很清楚，很深入，很多时候仅仅局限于表层，就例如，我用过单片机，像8051、STM32都玩过了，但真要问我寄存器是什么？程序怎么跑的？我大概率是很难一下子准确回答出来的。</p><p>我翻了翻大学课程，找到了大学的时候课程上老师推荐过的一些书，啊，原来早就学过的啊，那就拿出以前的相关书籍重新学习一下吧。</p><p>接下来，进入汇编语言的学习，阅读的书籍：《汇编语言-第四版-王爽》</p><blockquote><p>Tips：</p><p>通过网盘分享的文件：汇编语言-第四版-王爽.pdf 链接: <a href="https://pan.baidu.com/s/1TzkPpVvzBCpsAE803PXQGQ?pwd=hd6y" target="_blank" rel="noreferrer">https://pan.baidu.com/s/1TzkPpVvzBCpsAE803PXQGQ?pwd=hd6y</a> 提取码: hd6y</p></blockquote>',6)])])}const m=a(o,[["render",d]]);export{u as __pageData,m as default};
